exports.validateCatWeb = validateCatWeb;
exports.VALID_CLASSES = VALID_CLASSES;
exports.VALID_SCRIPT_PROPERTIES = VALID_SCRIPT_PROPERTIES;
exports.VALID_VALUES = VALID_VALUES;
exports.COLOR_KEYS = COLOR_KEYS;
exports.TRANSPARENCY_KEYS = TRANSPARENCY_KEYS;
exports.EVENT_IDS = EVENT_IDS;
exports.ACTION_IDS = ACTION_IDS;
exports.CONTROL_FLOW_ACTION_IDS = CONTROL_FLOW_ACTION_IDS;
exports.FORBIDDEN_PROPERTY_MAP = FORBIDDEN_PROPERTY_MAP;
exports.UDIM2_REGEX = UDIM2_REGEX;
exports.UDIM_REGEX = UDIM_REGEX;
exports.HEX_COLOR_REGEX = HEX_COLOR_REGEX;
exports.GLOBAL_ID_REGEX = GLOBAL_ID_REGEX;
